CREATE DATABASE IF NOT EXISTS lake_shore_id_editor; USE lake_shore_id_editor;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(150) DEFAULT '',role ENUM('admin','staff') NOT NULL DEFAULT 'staff',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE signatories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,position_title VARCHAR(150) DEFAULT '',signature_path VARCHAR(255) DEFAULT NULL,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE cards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_name VARCHAR(255) NOT NULL,id_type ENUM('COLLEGE','JUNIOR_HIGH','SENIOR_HIGH') NOT NULL DEFAULT 'COLLEGE',course VARCHAR(255),grade_level VARCHAR(50),section_name VARCHAR(100),student_number VARCHAR(100),student_id_number VARCHAR(100),lrn VARCHAR(100),academic_year VARCHAR(50),school_year VARCHAR(50),photo_path VARCHAR(255),address_line1 VARCHAR(255),address_line2 VARCHAR(255),emergency_label VARCHAR(255),emergency_contact VARCHAR(255),emergency_phone VARCHAR(100),terms_title VARCHAR(255),term_1 TEXT,term_2 TEXT,term_3 TEXT,institution_name VARCHAR(255),institution_address VARCHAR(255),mobile_no VARCHAR(255),telephone_no VARCHAR(255),email_address VARCHAR(255),signatory_id INT UNSIGNED,signatory_name VARCHAR(150),signature_path VARCHAR(255),created_by INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);